quarters_to_generate = [
    ("2023Q2", "2023-05-04", "quarterly_filings/2023_Q2.pdf", Q2_CONTEXT, "verified_decisions_2023_q2.csv"),
    ("2023Q3", "2023-08-03", "quarterly_filings/2023_Q3.pdf", Q3_CONTEXT, "verified_decisions_2023_q3.csv"),
    ("2023Q4", "2023-11-02", "quarterly_filings/2023_Q4.pdf", Q4_CONTEXT, "verified_decisions_2023_q4.csv"),
]

generated_quarters_data = {}

for q_code, dec_date, filing_path, ctx, out_filename in quarters_to_generate:
    dec_list = generate_quarter_decisions(q_code, dec_date, filing_path, ctx)
    assert len(dec_list) == 160
    out_path = os.path.join(DATASET_DIR, out_filename)
    with open(out_path, "w", newline="", encoding="utf-8") as f:
        writer = csv.DictWriter(f, fieldnames=FIELDNAMES)
        writer.writeheader()
        writer.writerows(dec_list)
    print(f"Generated {len(dec_list)} decisions for {q_code} -> {out_path}")
    generated_quarters_data[q_code] = dec_list

with open(BACKUP_ALL, "r", encoding="utf-8") as f:
    existing_all = list(csv.DictReader(f))

by_quarter = {}
for row in existing_all:
    q = row["case_id"].split("-")[1]
    if q not in by_quarter:
        by_quarter[q] = []
    by_quarter[q].append(row)

full_quarter_order = [
    "2023Q1", "2023Q2", "2023Q3", "2023Q4",
    "2024Q1", "2024Q2", "2024Q3",
    "2025Q1", "2025Q2", "2025Q3", "2025Q4"
]

all_integrated = []
for q in full_quarter_order:
    if q in generated_quarters_data:
        all_integrated.extend(generated_quarters_data[q])
    elif q in by_quarter:
        all_integrated.extend(by_quarter[q])

with open(BACKUP_ALL, "w", newline="", encoding="utf-8") as f:
    writer = csv.DictWriter(f, fieldnames=FIELDNAMES)
    writer.writeheader()
    writer.writerows(all_integrated)

print(f"Master backup updated with {len(all_integrated)} total decisions across {len(full_quarter_order)} quarters.")
